def esc(s):return html.escape(str(s))
def source(repo,path=''):return f'https://github.com/guykalati/{repo}/blob/{BRANCH}/{path}'
def table(headers,rows,cls=''):
 return '<div class="table-scroll"><table class="'+cls+'"><thead><tr>'+''.join('<th scope="col">'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def section(id,title,sub,body):return f'<section class="section" id="{id}"><div class="section-head"><h2>{title}</h2><p>{sub}</p></div>{body}</section>'
def flow(steps):return '<div class="flow">'+''.join(f'<div><b>{esc(a)}</b><span>{esc(b)}</span></div>' for a,b in steps)+'</div>'
def cards(cs):return '<div class="grid2">'+''.join(f'<div class="card"><h3>{t}</h3><p>{b}</p></div>' for t,b in cs)+'</div>'
def current_review(kind,repo):
 data=json.loads((REPOS/repo/'cv-closure/output/analysis.json').read_text())
 status=json.loads((REPOS/repo/'PROJECT_STATUS.json').read_text())
 if kind=='llm':
  rows=[[name.title(),r['n'],r['exact_matches'],f"{r['mean_token_f1']:.3f}"] for name,r in data['stages']['sft'].items() if name in ['answerable','unanswerable']]
  detail=table(['After SFT','Questions','Exact matches','Token F1'],rows)
  explanation='The same 106 questions improve and regress differently. The answerable/abstention split makes the remaining factual-recall problem visible. The larger literature queue still requires scientific admission.'
 elif kind=='rag':
  detail=table(['Retriever','Reference anchors at top 3','Questions with all anchors','Answers with valid citations'],[[name.upper() if name=='bm25' else name.title(),f"{r['anchor_hits']} / {r['required_anchors']}",f"{r['questions_with_all_anchors_at_3']} / 12",f"{r['answers_with_valid_citation']} / 12"] for name,r in data['summary'].items()])
  explanation='These deterministic checks use the frozen source phrases and saved contexts. They are independent of the model judge, but measure exact coverage and citation existence, not semantic correctness. No new repair or experiment-memory benefit is claimed.'
 else:
  detail=table(['Reference F classified as','N','S','V','F','Q'],[['384 fusion beats']+[data['fusion_error_destinations'][c] for c in 'NSVFQ']])
  explanation=f"The majority-class accuracy is {100*data['majority_accuracy']:.2f}%. I now independently recompute every class metric as well as the headline accuracy. Fusion recall remains zero; no threshold or checkpoint was selected from these test errors."
 links='<div class="source-links">'+''.join(f'<a href="{source(repo,path)}">{label} ↗</a>' for label,path in [('Analysis code','cv-closure/analyze_results.py'),('Saved analysis','cv-closure/output/analysis.json'),('Decisions','DECISIONS.md'),('Current status','PROJECT_STATUS.md'),('Verify locally','verify_project.py'),('Fresh audit','verification/2026-10-17-final.json')])+'</div>'
 return section('review','A closer check of the results','Implementation review · 17 October 2026',detail+'<p>'+explanation+'</p>'+cards([('Reproducible checks','One command verifies the saved evidence, derived analysis, offline regression tests and page links. Fresh audit reports are separate from historical results.'),('What remains to establish','The completed experiments are inspectable. Larger scientific expansion remains open; additional models or data are not treated as improvements before they pass the recorded checks.')])+links)
def shell(kind,repo,title,body,js='',guide=False):
 if not guide:body+=current_review(kind,repo)
 nav='<a href="index.html">Project</a><a href="guide.html">Study guide</a>'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(title)}. Guy Kalati's project, verified results and technical guide."><meta name="theme-color" content="#16202d"><title>{esc(title)} | Guy Kalati</title><style>{CSS}</style></head><body data-theme="{kind}"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="top-inner"><a class="brand" href="index.html">Guy Kalati<span>Applied ML / project notes</span></a><nav aria-label="Main">{nav}<a href="https://github.com/guykalati/{repo}/tree/{BRANCH}">GitHub ↗</a></nav></div>{'<div class="progress-shell"><div class="progress-fill" id="progress"></div></div>' if guide else ''}</header><main id="main" class="wrap">{body}</main><footer class="footer"><div class="wrap"><p>Guy Kalati · Saved experiments: 3–4 October 2026. Implementation review: 17 October 2026. Code, configurations and saved results are linked throughout. The current implementation used AI coding assistance and explicit artifact checks.</p><p>{'The original LLM coursework was individual work.' if kind=='llm' else 'The original course project was joint work; this page describes the subsequent reproduction, evaluation and implementation work.'} These pages describe completed experiments and their limits.</p></div></footer><script>{js}</script></body></html>'''
def hero(kind,title,lede,artifact,stats):
 return '<section class="hero"><p class="eyebrow">'+kind+'</p><div class="hero-grid"><div><h1>'+title+'</h1><p class="lede">'+lede+'</p><div class="actions"><a class="btn" href="#results">See the results</a><a class="btn secondary" href="guide.html">Technical study guide</a></div></div>'+artifact+'</div><div class="stats">'+''.join(f'<div class="stat"><strong>{a}</strong><span>{b}</span></div>' for a,b in stats)+'</div></section>'
def plot_curves(result):
 width,height=470,270;left,right,top,bottom=48,18,24,40;lo,hi=10,12.6
 def x(v):return left+(width-left-right)*v/200
 def y(v):return height-bottom-(height-top-bottom)*(v-lo)/(hi-lo)
 svg=f'<svg viewBox="0 0 {width} {height}" role="img" aria-labelledby="curve-title"><title id="curve-title">Recorded validation perplexity at the same training steps</title>'
 for tick in [10,11,12]:svg+=f'<line x1="{left}" y1="{y(tick)}" x2="{width-right}" y2="{y(tick)}" stroke="#ffffff20"/><text x="12" y="{y(tick)+4}" fill="#b6c1d2" font-size="11">{tick}</text>'
 for st in [0,50,100,150,200]:svg+=f'<text x="{x(st)}" y="{height-17}" text-anchor="middle" fill="#b6c1d2" font-size="11">{st}</text>'
 for name,color in [('attention','#b7adff'),('attention_mlp','#67e1bd')]:
  arm=result['cpt'][name];pts=[(0,arm['initial']['perplexity'])]+[(v['step'],v['validation']['perplexity']) for v in arm['history']]
  svg+='<polyline fill="none" stroke="'+color+'" stroke-width="3" points="'+' '.join(f'{x(a):.1f},{y(b):.1f}' for a,b in pts)+'"/>'
  a,b=pts[-1];svg+=f'<circle cx="{x(a)}" cy="{y(b)}" r="5" fill="{color}"/>'
 return svg+'</svg>'
ragrepo=items[1][1];ragr=REPOS/ragrepo;rag=json.loads((ragr/'cv-closure/output/result.json').read_text());rows=[json.loads(v) for v in (ragr/'cv-closure/output/rows.jsonl').read_text().splitlines()]
artifact='<div class="artifact"><p class="eyebrow">One saved repository repair</p><h3>The model requests.<br>The controller checks.</h3>'+''.join(f'<div style="border-top:1px solid #ffffff20;padding:13px 0;display:flex;gap:18px"><span style="color:#81ddca;font:12px ui-monospace;min-width:24px">{i+1:02}</span><span style="font-size:14px"><b>{a}</b><br><span style="color:#bbc9d3">{b}</span></span></div>' for i,(a,b) in enumerate([('Inspect candidate files','list_files → read_file'),('Apply an exact edit','replace_text validates one match'),('Request isolated tests','run_test returns an observation'),('Verify the final candidate','Target + regression: both exit 0')]))+'<p class="small">Summary of the PySnooper3 trace, not a simulated console. Eight tool calls; independent final evaluation.</p></div>'
body=hero('02 / Agents and retrieval','Repository repair.<br><em>Documentation QA.</em>','I built a bounded coding-agent controller, then added a documentation RAG benchmark with three retrieval methods. Saving the raw verdicts made it possible to catch mistakes in the evaluator as well as the answers.',artifact,[('8 tool calls','Verified successful repair trace'),('581 chunks','Eight Python documentation sources'),('36 cases','108 independently recomputed metrics')])
body+=section('build','Two systems, two acceptance checks','Python · Ollama · MiniLM · RAGAS',cards([('A coding agent with a restricted tool surface','The model can list files, read bounded excerpts, replace one exact match and request fixed tests. A gateway checks operations. The evaluation bridge runs isolated CPU jobs. Independent target and regression checks confirm the saved repair.'),('A retriever that can be compared fairly','I froze the source snapshots and 12 checked references before comparing BM25, dense cosine search and hybrid reciprocal rank fusion. Every strategy uses the same top-three context budget and local answer model.')])+flow([('Index the sources','Versioned HTML and chunk IDs'),('Retrieve top three','BM25 / dense / hybrid RRF'),('Generate with citations','Cached local Gemma model'),('Audit each verdict','Raw RAGAS calls and arithmetic')]))
body+=section('results','The complete retrieval comparison','12 questions per strategy · all metrics valid',table(['Strategy','Precision','Recall','Faithfulness','Full answer median'],[[s.upper() if s=='bm25' else s.title(),f'{r["ragas"]["context_precision"]["mean"]:.3f}',f'{r["ragas"]["context_recall"]["mean"]:.3f}',f'{r["ragas"]["faithfulness"]["mean"]:.3f}',f'{r["latency"]["query_to_answer_seconds"]["median_seconds"]:.2f} s'] for s,r in rag['summary'].items()])+'<div class="note"><p>Hybrid has the best observed precision and faithfulness in this small benchmark. Median retrieval is 0.343 s; the complete answer takes 21.03 s. A model-judged score does not establish answer correctness or better coding repairs.</p></div>')
body+=section('examples','A score needs its case','Recorded benchmark explorer · no live inference','<div class="explorer"><div class="controls"><label>Benchmark question<select id="question"></select></label><div class="chips">'+''.join(f'<button data-strategy="{s}" aria-pressed="{str(s=="hybrid").lower()}">{t}</button>' for s,t in [('bm25','BM25'),('dense','Dense'),('hybrid','Hybrid')])+'</div></div><p id="qtext"></p><div class="answer" id="answer" aria-live="polite"></div><div class="metric-row" id="metrics"></div><p class="case-note" id="case-note"></p><details><summary>Read the retrieved evidence</summary><div id="contexts"></div></details><p class="small" id="reference"></p></div>')
body+=section('errors','What the averages miss','Concrete failures, preserved unchanged',cards([('Faithful to the wrong API','BM25 retrieves Popen.communicate behavior for a subprocess.run timeout question. The answer is wrong for the task, even though faithfulness scores 1.0. The missing reference evidence is visible in precision and recall.'),('A correct option gets rejected','The mkdir answers use the right options. The judge gives faithfulness 0 because it objects to "should use" wording. Other verdicts misread valid chunk citations. I recorded the errors without replacing the original scores.')]))
body+=section('research','An experiment loop that can reject a proposal','Separate autoresearch-inspired work','<div class="card"><h3>The latest candidate did not beat the incumbent</h3><p>I added history retrieval, bounded proposals, candidate checks and independently reloaded evaluation to an autoresearch-style loop. A completed eight-head TinyStories candidate scored 0.91690 validation bits per byte versus the incumbent\'s 0.91219. Lower is better, so the incumbent stayed.</p><p class="small">This was a verified development experiment. It was not a completed paired comparison proving history retrieval improves model search. <a href="'+source(ragrepo,'research-workbench/AUTORESEARCH_STATEMENT_REPLAY_RESULT_2026-10-03.md')+'">Read the result ↗</a></p></div>')
body+=section('evidence','Follow a tool call or an answer','Saved evidence, not a highlight reel','<div class="source-links">'+''.join(f'<a href="{source(ragrepo,p)}">{label} ↗</a>' for label,p in [('Agent controller','research-workbench/implementation/repair_agent.py'),('Repair trace','research-workbench/implementation/repair_agent_success_pysnooper3_2026-09-29.json'),('RAG code','cv-closure/evaluate.py'),('All answers','cv-closure/output/rows.jsonl'),('Raw judge calls','cv-closure/output/judge_calls.jsonl'),('Independent audit','cv-closure/output/result_audit.json')])+'</div><p class="small">The answer and judge use the same local model. The benchmark has 12 questions; its means do not establish general RAG reliability. The separate agent tests include 11 controller/gateway unit checks.</p>')
js='const records='+json.dumps(rows).replace('</',r'<\/')+''';let strategy='hybrid';const sel=document.querySelector('#question');for(const r of records.filter(x=>x.strategy==='hybrid'))sel.add(new Option(r.id+' · '+r.question.slice(0,65),r.id));sel.value='py312_05';const notes={py312_01:'The mkdir options are correct, but the judge rejects normative wording. Faithfulness is 0 for all strategies.',py312_05:'BM25 follows the wrong API context and receives faithfulness 1. Dense/hybrid retrieve the run timeout behavior.',py312_06:'Dense/hybrid merge test failure and error outcomes despite faithfulness 1.',py312_08:'Some judge statements treat a valid citation ID as unsupported context.',py312_09:'Inspect the parameter style and the tuple/dictionary distinction; judge extraction also has errors.',py312_12:'No strategy gives the complete requested read_text → json.loads handoff. BM25 names json.load; dense omits the function; hybrid names JSONDecoder.'};function draw(){const r=records.find(x=>x.id===sel.value&&x.strategy===strategy);document.querySelector('#qtext').textContent=r.question;document.querySelector('#answer').textContent=r.response;document.querySelector('#reference').textContent='Checked reference: '+r.reference;document.querySelector('#case-note').textContent=notes[r.id]||'Compare the answer with its reference and retrieved text. The numerical verdict is a local-model judgment, not an expert correctness label.';const m=document.querySelector('#metrics');m.replaceChildren();for(const [name,value] of [['Precision',r.ragas.context_precision.value],['Recall',r.ragas.context_recall.value],['Faithfulness',r.ragas.faithfulness.value],['Full answer (s)',r.latency.query_to_answer_seconds]]){const s=document.createElement('span');s.textContent=name;const b=document.createElement('b');b.textContent=value.toFixed(3);s.append(b);m.append(s)}const c=document.querySelector('#contexts');c.replaceChildren();r.contexts.forEach(v=>{const h=document.createElement('h4');h.textContent=v.id;const p=document.createElement('p');p.textContent=v.text;c.append(h,p)})}sel.addEventListener('change',draw);document.querySelectorAll('[data-strategy]').forEach(b=>b.addEventListener('click',()=>{strategy=b.dataset.strategy;document.querySelectorAll('[data-strategy]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw()}));draw();'''
(ragr/'showcase/index.html').write_text(shell('rag',ragrepo,'Bounded coding agent and RAG evaluation',body,js))

