render="import {marked} from '"+MARKED+"';let s='';for await(const c of process.stdin)s+=c;process.stdout.write(marked.parse(s));"
for kind,repo,label in [items[1]]:
 folder=REPOS/repo/'showcase';md=(folder/'guide.md').read_text()
