 body='<div class="guide-head"><p class="eyebrow">Personal study guide / '+label+'</p><h1>'+title+'</h1><p class="lede">Build the explanation from first principles, follow the actual code, then defend the choices and results.</p><div class="guide-tools"><button id="answers">Show interview answers</button><button id="print">Print / save PDF</button><span class="small">About '+str(minutes)+' min reading · plus exercises</span></div></div><div class="guide-grid"><aside class="toc"><label for="toc-search">Find a section</label><input id="toc-search" type="search" placeholder="Masking, latency, split…"><nav aria-label="Guide sections">'+''.join(f'<a href="#{s}">{esc(t)}</a>' for s,t in toc)+'</nav><p class="small" id="study-progress" aria-live="polite">0 sections practised</p></aside><article class="article">'+rendered+'</article></div>'
 js='''const article=document.querySelector('.article'),heads=[...article.querySelectorAll('h2')],key='guy-guide-'+document.body.dataset.theme;let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')}catch{}heads.forEach(h=>{const next=heads[heads.indexOf(h)+1],label=document.createElement('label');label.className='study-check';const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!state[h.id];label.append(cb,'I can explain this section without notes');if(next)next.before(label);else article.append(label);cb.addEventListener('change',()=>{state[h.id]=cb.checked;try{localStorage.setItem(key,JSON.stringify(state))}catch{}progress()})});function progress(){const done=heads.filter(h=>state[h.id]).length;document.querySelector('#study-progress').textContent=done+' / '+heads.length+' sections practised';document.querySelector('#progress').style.width=(100*done/heads.length)+'%'}progress();document.querySelector('#toc-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.toc nav a').forEach(a=>{const h=document.getElementById(a.hash.slice(1));let text=h.textContent,node=h.nextElementSibling;while(node&&node.tagName!=='H2'){text+=' '+node.textContent;node=node.nextElementSibling}a.hidden=!text.toLowerCase().includes(q)})});let all=false;document.querySelector('#answers').addEventListener('click',e=>{all=!all;article.querySelectorAll('details').forEach(d=>d.open=all);e.target.textContent=all?'Hide interview answers':'Show interview answers'});let prior=[];window.addEventListener('beforeprint',()=>{prior=[...article.querySelectorAll('details')].map(d=>d.open);article.querySelectorAll('details').forEach(d=>d.open=true)});window.addEventListener('afterprint',()=>article.querySelectorAll('details').forEach((d,i)=>d.open=prior[i]));document.querySelector('#print').addEventListener('click',()=>window.print());'''
